INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (14, 9, 'theory', 'Quiz: adders and comparison');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 9, 0, 'Which gates make up a half adder?', '["Two ANDs", "XOR (for the sum) and AND (for the carry)", "OR and NOT", "Two NORs"]', 1, 'The sum of two bits is exclusive OR, the carry is AND. The half adder does not accept a carry from below, so multi-bit numbers need a full adder.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 9, 1, 'What is the carry of a full adder when A = 1, B = 1, Cin = 0?', '["0", "Undefined", "Depends on the clock frequency", "1"]', 3, 'The carry is one if at least two inputs are ones. Here there are two: sum 0, carry 1.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 9, 2, 'How does an adder-subtractor compute A − B?', '["It uses a separate subtraction circuit", "It adds A and B and inverts the result", "It inverts B and feeds a one into the carry input: A + not B + 1", "It subtracts bit by bit without a carry"]', 2, 'In two''s complement −B = not B + 1. The Sub signal simultaneously switches the XOR gates on the B input and the carry input of the lowest position.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 9, 3, 'In four bits, 0111 + 0001 = 1000 is computed in signed code. What happened?', '["Signed overflow: 7 + 1 gave −8", "Nothing special", "A carry out of the highest position", "An adder error"]', 0, 'There is no carry, but the result is out of range: we added two positive numbers and got a negative one. This is the V flag.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (14, 9, 4, 'Why is a ripple-carry adder slow for a large number of bits?', '["It has too few gates", "It runs at half the frequency", "The result cannot be read until the end of the clock cycle", "The carry has to pass through all positions in turn"]', 3, 'The delay grows linearly with the number of bits. Carry-lookahead circuits compute all the carries in parallel at the cost of extra gates.');
